WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.DEL_YN = 'N'
  /* MANAGE 탭: 작성중/개설/진행중만(종료/취소는 이력 탭) */
  AND A.STATUS_CD IN ('DRAFT', 'OPENED', 'IN_PROGRESS')
  /* 노드관리자 스코프: 접근가능 사업장 + 개설자 노드(자기노드+자손) */



