mapper.select:
/* AppAdminTbmMapper.existsAccessibleSite */
SELECT EXISTS(
	SELECT 1
	FROM TB_USER_SITE_AUTH USA
	INNER JOIN TB_SITE S
		ON S.CMPNY_CD = USA.CMPNY_CD
	   AND S.SITE_CD = USA.SITE_CD
	WHERE USA.CMPNY_CD = #{gvCmpnyCd}
	  AND USA.USER_CD = #{gvUserCd}
	  AND USA.SITE_CD = #{siteCd}
	  AND USA.USE_YN = 'Y'
	  AND S.USE_YN = 'Y'
)

/* AppAdminTbmMapper.selectContentOptions */ SELECT A.MTRL_CD AS mtrlCd , A.TITLE AS title , A.MTRL_TYPE AS mtrlType , BD.BAIM_VAL_D_NM AS mtrlTypeNm , A.SITE_CD AS siteCd , CASE WHEN A.SITE_CD IS NULL THEN 'Y' ELSE 'N' END AS isCommonContent , ( SELECT COUNT(I.MTRL_ITEM_CD) FROM TB_TBM_EDU_MTRL_ITEM I WHERE I.MTRL_CD = A.MTRL_CD AND I.USE_YN = 'Y' ) AS itemCnt FROM TB_TBM_EDU_MTRL A LEFT OUTER JOIN TB_BAIM_VAL_D BD ON ( BD.CMPNY_CD = A.CMPNY_CD AND BD.BAIM_VAL_CD = 'COM003' AND BD.BAIM_VAL_D_CD = A.MTRL_TYPE AND BD.USE_YN = 'Y' ) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.USE_YN = 'Y' /* 노드관리자: 접근가능 사업장 자료 + 회사공통(SITE_CD IS NULL). companyWide=전사. */
AND ( A.SITE_CD IS NULL OR A.SITE_CD IN
#{sc}
)
AND A.SITE_CD IS NULL
AND A.SITE_CD IS NULL
AND (A.SITE_CD IS NULL OR A.SITE_CD = #{siteCd})
AND A.TITLE LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.SITE_CD IS NOT NULL, A.TITLE LIMIT 200

/* AppAdminTbmMapper.selectRiskOptions */ SELECT A.SITE_CD AS siteCd , A.PROCESS_CD AS processCd , C.BAIM_VAL_D_NM AS processNm , A.RISK_TYPE_CD AS riskTypeCd , D.RISK_TYPE_NM AS riskTypeNm , A.HAZARD_CD AS hazardCd , CASE WHEN A.HAZARD_CD = 'self' THEN A.ASSESSMENT_DESC ELSE E.HAZARD_NM END AS hazardNm , A.ASSESSMENT_CD AS assessmentCd , A.ASSESSMENT_STATUS AS assessmentStatus , B.SYST_VAL_D_NM AS assessmentStatusNm FROM TB_RISK_ASSESSMENT A LEFT OUTER JOIN ( SELECT G.SYST_VAL_D_CD, G.SYST_VAL_D_NM FROM TB_SYST_VAL_D G WHERE G.SYST_VAL_CD = 'SYS011' AND G.USE_YN = 'Y' ) B ON ( A.ASSESSMENT_STATUS = B.SYST_VAL_D_CD ) LEFT OUTER JOIN TB_BAIM_VAL_D C ON ( C.CMPNY_CD = A.CMPNY_CD AND C.BAIM_VAL_CD = 'COM002' AND C.BAIM_VAL_D_CD = A.PROCESS_CD AND C.USE_YN = 'Y' ) LEFT OUTER JOIN TB_RISK_TYPE D ON ( A.CMPNY_CD = D.CMPNY_CD AND A.RISK_TYPE_CD = D.RISK_TYPE_CD ) LEFT OUTER JOIN TB_RISK_SITE_HAZARD E ON ( A.CMPNY_CD = E.CMPNY_CD AND A.RISK_TYPE_CD = E.RISK_TYPE_CD AND A.HAZARD_CD = E.HAZARD_CD ) WHERE A.CMPNY_CD = #{gvCmpnyCd} /* 노드관리자: 접근가능 사업장만. companyWide=전사. */
AND A.SITE_CD IN
#{sc}
AND 1 = 0
AND A.SITE_CD = #{siteCd}
AND A.PROCESS_CD = #{processCd}
ORDER BY A.SITE_CD, A.PROCESS_CD, A.RISK_TYPE_CD, A.HAZARD_CD LIMIT 200

mapper.update:
/* AppAdminTbmMapper.startSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD		= 'IN_PROGRESS'
	, STARTED_AT	= NOW()
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  /* 멱등/경합 가드: 개설(OPENED) 상태에서만 시작 전이 */
  AND STATUS_CD = 'OPENED'

/* AppAdminTbmMapper.endSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD		= 'COMPLETED'
	, ENDED_AT		= NOW()
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  /* 멱등/경합 가드: 진행중(IN_PROGRESS) 상태에서만 종료 전이 */
  AND STATUS_CD = 'IN_PROGRESS'

/* AppAdminTbmMapper.autoCompleteOnEnd */
UPDATE TB_TBM_ATTENDANCE
SET
	EXIT_AT					= NOW()
	, COMPLETION_STATUS_CD	= 'COMPLETED'
	, STATUS_UPDATED_BY		= #{gvUserCd}
	, STATUS_UPDATED_AT		= NOW()
	, UPDATE_NO				= #{gvUserCd}
	, UPDATE_DATE			= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND EXIT_AT IS NULL
  AND DEL_YN = 'N'

/* AppAdminTbmMapper.upsertSessionStatePlaying */
INSERT INTO TB_TBM_SESSION_STATE (
	CMPNY_CD
	, SESSION_CD
	, CURRENT_SLIDE_INDEX
	, SYNC_STATE_CD
	, LAST_UPDATED_BY
	, INSERT_NO
	, INSERT_DATE
) VALUES (
	#{gvCmpnyCd}
	, #{sessionCd}
	, 0
	, 'PLAYING'
	, #{gvUserCd}
	, #{gvUserCd}
	, NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
	SYNC_STATE_CD		= NEW.SYNC_STATE_CD
	, LAST_UPDATED_BY	= NEW.LAST_UPDATED_BY
	, UPDATE_NO			= NEW.INSERT_NO
	, UPDATE_DATE		= NOW()

mapper.select:
/* AppAdminTbmMapper.selectSessionAttendeesAdmin */ SELECT AT.ATTENDANCE_CD AS attendanceCd , CASE WHEN AT.USER_TYPE_CD = 'REGULAR' THEN RU.USER_NM ELSE DU.USER_NM END AS userNm , AT.USER_TYPE_CD AS userTypeCd , ND.NODE_NM AS deptNm , DATE_FORMAT(AT.ENTRY_AT, '%Y-%m-%d %H:%i') AS entryAt , (AT.EXIT_AT IS NOT NULL) AS exited , DATE_FORMAT(AT.EXIT_AT, '%Y-%m-%d %H:%i') AS exitAt , AT.COMPLETION_STATUS_CD AS completionStatusCd FROM TB_TBM_ATTENDANCE AT LEFT OUTER JOIN TB_USER RU ON ( AT.USER_TYPE_CD = 'REGULAR' AND AT.CMPNY_CD = RU.CMPNY_CD AND AT.USER_CD = RU.USER_CD ) LEFT OUTER JOIN TB_DAILY_USER DU ON ( AT.USER_TYPE_CD = 'DAILY' AND AT.CMPNY_CD = DU.CMPNY_CD AND AT.USER_CD = DU.USER_CD ) LEFT OUTER JOIN TB_SITE_NODE ND ON ( AT.USER_TYPE_CD = 'REGULAR' AND RU.CMPNY_CD = ND.CMPNY_CD AND RU.SITE_CD = ND.SITE_CD AND RU.NODE_CD = ND.NODE_CD ) WHERE AT.CMPNY_CD = #{gvCmpnyCd} AND AT.SESSION_CD = #{sessionCd} AND AT.DEL_YN = 'N' /* phase=LIVE: 입실자만(ENTRY_AT IS NOT NULL). COMPLETED: 출결 전체 */
AND AT.ENTRY_AT IS NOT NULL
ORDER BY AT.ENTRY_AT IS NULL, AT.ENTRY_AT, AT.ATTENDANCE_CD LIMIT 500

mapper.update:
/* AppAdminTbmMapper.forceExitAttendee */
UPDATE TB_TBM_ATTENDANCE
SET
	EXIT_AT						= NOW()
	, EXIT_TYPE_CD				= 'MANAGER_FORCED'
	, EXIT_BY_MANAGER_USER_CD	= #{gvUserCd}
	, EXIT_FORCED_REASON		= #{exitForcedReason}
	, COMPLETION_STATUS_CD		= 'NOT_COMPLETED'
	, STATUS_UPDATED_BY			= #{gvUserCd}
	, STATUS_UPDATED_AT			= NOW()
	, UPDATE_NO					= #{gvUserCd}
	, UPDATE_DATE				= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND ATTENDANCE_CD = #{attendanceCd}
  AND EXIT_AT IS NULL
  AND DEL_YN = 'N'

/* AppAdminTbmMapper.updateAttendeeCompletion */
UPDATE TB_TBM_ATTENDANCE
SET
	COMPLETION_STATUS_CD	= #{completionStatusCd}
	, NOT_COMPLETED_REASON	= IFNULL(#{notCompletedReason}, NOT_COMPLETED_REASON)
	, STATUS_UPDATED_BY		= #{gvUserCd}
	, STATUS_UPDATED_AT		= NOW()
	, UPDATE_NO				= #{gvUserCd}
	, UPDATE_DATE			= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND ATTENDANCE_CD = #{attendanceCd}
  AND DEL_YN = 'N'

